67	// Fast exp2 approximation via PTX ex2.approx.f32.
68	// Used in Mamba scan: exp(A * dt) = exp2(A * dt / ln2).
69	__device__ __forceinline__ float ptx_exp2(float x) {
70	    float r;
71	    asm("ex2.approx.f32 %0, %1;" : "=f"(r) : "f"(x));
