94	// ── Dtype cast helpers (intrinsic-based) ────────────────────────────────
95	// static_cast between {__half,__nv_bfloat16} and float is rejected under
96	// torch's -D__CUDA_NO_HALF_CONVERSIONS__ / -D__CUDA_NO_BFLOAT16_CONVERSIONS__
97	// (CUDAExtension default — strips operator float()/the float ctor). Route
98	// half/bf16<->float through the always-available conversion intrinsics; the
99	// generic templates leave float/int casts unchanged.
100	template <typename T> __device__ __forceinline__ float to_float(T v) { return static_cast<float>(v); }
101	template <> __device__ __forceinline__ float to_float<__half>(__half v) { return __half2float(v); }
102	template <> __device__ __forceinline__ float to_float<__nv_bfloat16>(__nv_bfloat16 v) { return __bfloat162float(v); }
103	template <typename T> __device__ __forceinline__ T from_float(float v) { return static_cast<T>(v); }
104	template <> __device__ __forceinline__ __half from_float<__half>(float v) { return __float2half(v); }
105	template <> __device__ __forceinline__ __nv_bfloat16 from_float<__nv_bfloat16>(float v) { return __float2bfloat16(v); }
