132	// ── SMEM-based attention kernel (default for tiny seq_len) ─────────────
133	// One block per (batch, head). Each thread cooperates on the matmul.
134	// Max seq_len supported: 32 (17x17 scores = 289 floats in SMEM).
135	
136	template <typename ActT, int kHeadDim, bool kCausal>
137	__global__ void __launch_bounds__(128, 4)
138	smem_attention_fwd_kernel(
139	    const ActT* __restrict__ q,     // [B, H, N, D]
140	    const ActT* __restrict__ k,
141	    const ActT* __restrict__ v,
142	    ActT* __restrict__ out,
143	    float* __restrict__ softmax_lse, // [B, H, N] or nullptr
144	    int seq_len, float scale
145	) {
146	    const int bh = blockIdx.x;              // flattened (batch, head) index
147	    const int tid = threadIdx.x;
148	    const int N = seq_len;
149	    const int D = kHeadDim;
150	    // 64-bit base offset: bh = batch*n_heads can be large, so bh*N*D may exceed
151	    // INT_MAX even though N (<=32) keeps the in-block N*N / N*D loops in int.
152	    const int64_t base = static_cast<int64_t>(bh) * N * D;
153	
154	    // Shared memory: scores[N][N] + row_max[N] + row_sum[N]
155	    extern __shared__ float smem[];
156	    float* scores  = smem;                  // N * N
157	    float* row_max = scores + N * N;        // N
158	    float* row_sum = row_max + N;           // N
159	
160	    // Step 1: Compute S = Q K^T * scale, with optional causal mask
161	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
162	        int i = idx / N;  // query row
163	        int j = idx % N;  // key column
164	        if constexpr (kCausal) {
165	            // Unified mask sentinel (-1e30f), matching the CUTLASS softmax path
166	            // (fmha_softmax_kernel). After exp(score - row_max) this underflows
167	            // to 0 in both FP32 and post-bf16-cast probs.
168	            if (j > i) { scores[idx] = -1e30f; continue; }
169	        }
170	        float dot = 0.0f;
171	        for (int d = 0; d < D; d++) {
172	            dot += to_float(q[base + i * D + d])
173	                 * to_float(k[base + j * D + d]);
174	        }
175	        scores[idx] = dot * scale;
176	    }
177	    __syncthreads();
178	
179	    // Step 2: Row-wise softmax (online stable via max subtraction)
180	    for (int i = tid; i < N; i += blockDim.x) {
181	        float m = -1e30f;   // unified sentinel (matches CUTLASS softmax path)
182	        for (int j = 0; j < N; j++) m = fmaxf(m, scores[i * N + j]);
183	        row_max[i] = m;
184	        float s = 0.0f;
185	        for (int j = 0; j < N; j++) {
186	            float e = ptx_expf(scores[i * N + j] - m);
187	            scores[i * N + j] = e;
188	            s += e;
189	        }
190	        float inv_s = 1.0f / fmaxf(s, 1e-12f);
191	        for (int j = 0; j < N; j++) scores[i * N + j] *= inv_s;
192	        row_sum[i] = s;  // keep for lse
193	        if (softmax_lse != nullptr)
194	            softmax_lse[static_cast<int64_t>(bh) * N + i] = m + logf(fmaxf(s, 1e-12f));
195	    }
196	    __syncthreads();
197	
198	    // Step 3: Out = Softmax(S) * V
199	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
200	        int i = idx / D;
201	        int d = idx % D;
202	        float acc = 0.0f;
203	        for (int j = 0; j < N; j++) {
204	            acc += scores[i * N + j] * to_float(v[base + j * D + d]);
205	        }
206	        out[base + idx] = from_float<ActT>(acc);
207	    }
208	}
