210	#ifdef WITH_CUTLASS
211	// ─────────────────────────────────────────────────────────────────────────
212	//  Sm90 collective FMHA forward (TMA + WGMMA, FP32 accumulate)
213	//
214	//  Implemented as two Sm90 GemmUniversal calls per (batch, head):
215	//      S = Q · Kᵀ          (M=N=seq_len, K=head_dim)   -> FP32 scores
216	//      softmax(S * scale)  (causal mask if kCausal)     -> FP32 probs P
217	//      O = P · V           (M=seq_len, N=head_dim, K=seq_len)
218	//  All matmuls accumulate in FP32 and emit Hopper WGMMA/TMA instructions via
219	//  CollectiveBuilder<arch::Sm90, OpClassTensorOp, ...>. This replaces the old
220	//  the default device::Gemm (no arch tag) default which compiled the Sm70 SIMT path.
221	//
222	//  A full single-kernel Sm90 fused-MHA collective is intentionally not inlined
223	//  here (too large); the two-GEMM + softmax decomposition is clearly correct
224	//  and shares the same WGMMA/TMA mainloop. The tiny-seq_len SMEM fallback
225	//  kernel (non-CUTLASS path) is left untouched.
226	// ─────────────────────────────────────────────────────────────────────────
227	
228	// Element trait: map activation type -> CUTLASS input element. FP32 maps to
229	// cutlass::tfloat32_t — the LIVE FP32 tensor-core FMHA path: the QKᵀ and P·V
230	// WGMMA mainloops read the float buffers as TF32 (10-bit mantissa, FP32
231	// accumulate). The intermediate scores S and probs P stay FP32.
232	template <typename ActT> struct cutlass_elem;
233	template <> struct cutlass_elem<__half>        { using type = cutlass::half_t; };
234	template <> struct cutlass_elem<__nv_bfloat16> { using type = cutlass::bfloat16_t; };
235	template <> struct cutlass_elem<float>         { using type = cutlass::tfloat32_t; };
236	
237	// The Sm90 collective FMHA path supports half/bf16 directly and FP32 via the
238	// TF32 tensor-core MMA (cutlass_elem<float>=tfloat32_t). FP32 attention uses
239	// the TF32 collective by DEFAULT. Define SG_FORCE_SCALAR_FP32 to force the
240	// exact-FP32 SMEM attention kernel instead. 🟡 numeric parity: TF32 (10-bit
241	// mantissa) is NOT bit-identical to the scalar SMEM FP32 (23-bit) path — the
242	// accepted FP32 tensor-core precision tradeoff, not a bug.
243	template <typename ActT> struct cutlass_fmha_supported { static constexpr bool value = false; };
244	template <> struct cutlass_fmha_supported<__half>        { static constexpr bool value = true; };
245	template <> struct cutlass_fmha_supported<__nv_bfloat16> { static constexpr bool value = true; };
246	#ifndef SG_FORCE_SCALAR_FP32
247	template <> struct cutlass_fmha_supported<float>         { static constexpr bool value = true; };
248	#endif
