250	// Per-thread CUTLASS workspace (lazily grown). Reused across calls.
251	inline void* fmha_get_workspace(size_t bytes) {
252	    static thread_local void*  ws_ptr   = nullptr;
253	    static thread_local size_t ws_bytes = 0;
254	    if (bytes > ws_bytes) {
255	        if (ws_ptr) cudaFree(ws_ptr);
256	        if (cudaMalloc(&ws_ptr, bytes) != cudaSuccess) {
257	            ws_ptr = nullptr; ws_bytes = 0; return nullptr;
258	        }
259	        ws_bytes = bytes;
260	    }
261	    return ws_ptr;
262	}
263	
264	// Per-thread FMHA scratch (S/P/O), lazily grown. Mirrors fmha_get_workspace:
265	// one grow-only device buffer per slot, reused across forward calls so the
266	// hot path no longer pays a cudaMalloc/cudaFree per call. Each slot has its
267	// own static so the three buffers never alias. Lifetime = process lifetime
268	// (intentional — the buffer is reused; sized to the largest request so far).
269	template <int kSlot>
270	inline void* fmha_get_scratch(size_t bytes) {
271	    static thread_local void*  ptr   = nullptr;
272	    static thread_local size_t cap   = 0;
273	    if (bytes > cap) {
274	        if (ptr) cudaFree(ptr);
275	        if (cudaMalloc(&ptr, bytes) != cudaSuccess) {
276	            ptr = nullptr; cap = 0; return nullptr;
277	        }
278	        cap = bytes;
279	    }
280	    return ptr;
281	}
