283	// Generic Sm90 GEMM: C[MxN] = A[MxK] * B[KxN], FP32 out, FP32 accumulate.
284	// A is RowMajor [M,K]. B layout is a template parameter:
285	//   - ColumnMajor B + physical [N,K] row-major data  => computes A·Bᵀ (QKᵀ)
286	//   - RowMajor    B + physical [K,N] row-major data  => computes A·B  (P·V)
287	// strideB_dims = logical {N, K, 1} so the packed stride matches the physical
288	// row-major [N,K] (QKᵀ) / [K,N] (PV) buffer respectively.
289	template <typename ElementInput, typename LayoutBT>
290	inline cudaError_t fmha_sm90_gemm(
291	    int M, int N, int K,
292	    const void* A, const void* B, float* C,
293	    cudaStream_t stream)
294	{
295	    using ElementA   = ElementInput;
296	    using ElementB   = ElementInput;
297	    using ElementC   = float;
298	    using ElementAcc = float;
299	    using LayoutA    = cutlass::layout::RowMajor;
300	    using LayoutB    = LayoutBT;
301	    using LayoutC    = cutlass::layout::RowMajor;
302	
303	    constexpr int AlignA = 128 / cutlass::sizeof_bits<ElementA>::value;
304	    constexpr int AlignB = 128 / cutlass::sizeof_bits<ElementB>::value;
305	    constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementC>::value;
306	
307	    using TileShape    = cute::Shape<cute::_128, cute::_128, cute::_64>;
308	    using ClusterShape = cute::Shape<cute::_1, cute::_1, cute::_1>;
309	
310	    using CollectiveEpilogue =
311	        typename cutlass::epilogue::collective::CollectiveBuilder<
312	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
313	            TileShape, ClusterShape,
314	            cutlass::epilogue::collective::EpilogueTileAuto,
315	            ElementAcc, ElementAcc,
316	            ElementC, LayoutC, AlignC,
317	            ElementC, LayoutC, AlignC,
318	            cutlass::epilogue::collective::EpilogueScheduleAuto
319	        >::CollectiveOp;
320	
321	    using CollectiveMainloop =
322	        typename cutlass::gemm::collective::CollectiveBuilder<
323	            cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
324	            ElementA, LayoutA, AlignA,
325	            ElementB, LayoutB, AlignB,
326	            ElementAcc,
327	            TileShape, ClusterShape,
328	            cutlass::gemm::collective::StageCountAutoCarveout<
329	                static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
330	            cutlass::gemm::collective::KernelScheduleAuto
331	        >::CollectiveOp;
332	
333	    using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
334	        cute::Shape<int, int, int, int>,
335	        CollectiveMainloop, CollectiveEpilogue>;
336	    using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
337	
338	    using StrideA = typename Gemm::GemmKernel::StrideA;
339	    using StrideB = typename Gemm::GemmKernel::StrideB;
340	    using StrideC = typename Gemm::GemmKernel::StrideC;
341	
342	    StrideA stride_a = cutlass::make_cute_packed_stride(StrideA{}, {M, K, 1});
343	    StrideB stride_b = cutlass::make_cute_packed_stride(StrideB{}, {N, K, 1});
344	    StrideC stride_c = cutlass::make_cute_packed_stride(StrideC{}, {M, N, 1});
345	
346	    typename Gemm::Arguments args{
347	        cutlass::gemm::GemmUniversalMode::kGemm,
348	        {M, N, K, 1},
349	        { reinterpret_cast<const ElementA*>(A), stride_a,
350	          reinterpret_cast<const ElementB*>(B), stride_b },
351	        { {ElementAcc(1.0f), ElementAcc(0.0f)},
352	          C, stride_c, C, stride_c }
353	    };
354	
355	    Gemm op;
356	    if (op.can_implement(args) != cutlass::Status::kSuccess)
357	        return cudaErrorNotSupported;
358	    size_t ws_size = Gemm::get_workspace_size(args);
359	    void*  ws = (ws_size > 0) ? fmha_get_workspace(ws_size) : nullptr;
360	    if (ws_size > 0 && ws == nullptr) return cudaErrorMemoryAllocation;
361	    if (op.initialize(args, ws, stream) != cutlass::Status::kSuccess)
362	        return cudaErrorUnknown;
363	    return (op.run(stream) == cutlass::Status::kSuccess)
364	               ? cudaSuccess : cudaErrorUnknown;
365	}
366	
367	// In-place row-wise softmax of an [N x N] FP32 score matrix, scaled, with
368	// optional causal mask. Casts the result into ActT probs buffer P.
369	template <typename ActT, bool kCausal>
370	__global__ void fmha_softmax_kernel(
371	    const float* __restrict__ S,   // [N, N] raw scores (Q·Kᵀ)
372	    ActT* __restrict__ P,          // [N, N] softmax probabilities (ActT)
373	    float* __restrict__ lse,       // [N] log-sum-exp or nullptr
374	    int N, float scale)
375	{
376	    namespace prim = ::sg::sm90::primitives;
377	    int i = blockIdx.x;            // query row
378	    if (i >= N) return;
379	    // Shared layout: sh[N] (working/scaled buffer) followed by sraw[N], the
380	    // cp.async raw-S staging buffer. Caller allocates 2*N floats (see launch).
381	    extern __shared__ float sh[];  // sh[0..N) | sraw[0..N)
382	    float* sraw = sh + N;
383	    int tid = threadIdx.x;
384	
385	    // ── §4.2 cp.async background staging of the raw S row into `sraw` ──────
386	    // The raw row S[i*N + 0..N) is the memory-bound global->shared load that
387	    // precedes the (latency-bound) softmax. We hand-issue cp.async.ca (4B,
388	    // scalar float) copies tile-by-tile, keeping SG_TUNED_ASYNC_DEPTH groups
389	    // in flight so the global-load latency overlaps the address math / issue
390	    // of later tiles. Each "tile" is one strided pass of blockDim.x elements.
391	    // Clamp the pipeline depth to a sane maximum.
392	    constexpr int kAsyncDepth =
393	        (SG_TUNED_ASYNC_DEPTH < 1) ? 1
394	      : (SG_TUNED_ASYNC_DEPTH > 4) ? 4 : SG_TUNED_ASYNC_DEPTH;
395	    const int bdx    = blockDim.x;
396	    const int nTiles = (N + bdx - 1) / bdx;          // tiles along the row
397	    const float* Srow = S + (size_t)i * N;
398	
399	    auto issue_tile = [&](int t) {
400	        const int j = t * bdx + tid;
401	        if (j < N) {
402	            // 4-byte (.ca) async copy S[i*N+j] -> sraw[j]; committed as a group.
403	            prim::cp_async_ca_4(&sraw[j], &Srow[j]);
404	        }
405	        prim::cp_async_commit();
406	    };
407	
408	    // Prime the pipeline with up to kAsyncDepth groups.
409	    int issued = 0;
410	    #pragma unroll
411	    for (int d = 0; d < kAsyncDepth; ++d) {
412	        if (issued < nTiles) { issue_tile(issued); ++issued; }
413	    }
414	
415	    // load + mask + find max, consuming the staged tiles as they land.
416	    float m = -1e30f;
417	    for (int t = 0; t < nTiles; ++t) {
418	        // Wait until at most (kAsyncDepth-1) groups remain in flight, i.e. the
419	        // group feeding tile `t` has landed in `sraw`. Then issue one more to
420	        // keep the pipe full.
421	        prim::cp_async_wait_group<kAsyncDepth - 1>();
422	        __syncthreads();                  // sraw[tile t] visible to all threads
423	        const int j = t * bdx + tid;
424	        if (j < N) {
425	            float v = sraw[j] * scale;    // byte-identical to S[i*N+j]*scale
426	            if (kCausal && j > i) v = -1e30f;
427	            sh[j] = v;
428	            m = fmaxf(m, v);
429	        }
430	        if (issued < nTiles) { issue_tile(issued); ++issued; }
431	        // No second sync needed: tiles write disjoint sraw[] regions (full-row
432	        // buffer, no slot reuse), so the next tile's wait+sync is sufficient.
433	    }
434	    prim::cp_async_wait_all();           // drain any tail groups still in flight
435	    __syncthreads();
436	    // block-wide max reduction (simple shared-mem tree over warps)
437	    __shared__ float red[32];
438	    for (int o = WARP_SIZE / 2; o > 0; o >>= 1)
439	        m = fmaxf(m, SHFL_DOWN_SYNC(FULL_WARP_MASK, m, o));
440	    if ((tid & (WARP_SIZE - 1)) == 0) red[tid / WARP_SIZE] = m;
441	    __syncthreads();
442	    if (tid == 0) {
443	        float mm = -1e30f;
444	        int nwarp = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
445	        for (int w = 0; w < nwarp; w++) mm = fmaxf(mm, red[w]);
446	        red[0] = mm;
447	    }
448	    __syncthreads();
449	    float row_max = red[0];
450	
451	    // exp + sum
452	    float s = 0.0f;
453	    for (int j = tid; j < N; j += blockDim.x) {
454	        float e = ptx_expf(sh[j] - row_max);
455	        sh[j] = e;
456	        s += e;
457	    }
458	    for (int o = WARP_SIZE / 2; o > 0; o >>= 1)
459	        s += SHFL_DOWN_SYNC(FULL_WARP_MASK, s, o);
460	    if ((tid & (WARP_SIZE - 1)) == 0) red[tid / WARP_SIZE] = s;
461	    __syncthreads();
462	    if (tid == 0) {
463	        float ss = 0.0f;
464	        int nwarp = (blockDim.x + WARP_SIZE - 1) / WARP_SIZE;
465	        for (int w = 0; w < nwarp; w++) ss += red[w];
466	        red[0] = ss;
467	    }
468	    __syncthreads();
469	    float row_sum = red[0];
470	    float inv = 1.0f / fmaxf(row_sum, 1e-12f);
471	
472	    for (int j = tid; j < N; j += blockDim.x)
473	        P[i * N + j] = from_float<ActT>(sh[j] * inv);
474	    if (lse != nullptr && tid == 0)
475	        lse[i] = row_max + logf(fmaxf(row_sum, 1e-12f));
476	}
