478	// Cast FP32 O accumulator -> ActT output.
479	template <typename ActT>
480	__global__ void fmha_cast_kernel(const float* __restrict__ src,
481	                                 ActT* __restrict__ dst, int n) {
482	    int idx = blockIdx.x * blockDim.x + threadIdx.x;
483	    if (idx < n) dst[idx] = from_float<ActT>(src[idx]);
484	}
