486	template <typename ActT, int kHeadDim, bool kCausal>
487	cudaError_t cutlass_fmha_forward(
488	    const ActT* q, const ActT* k, const ActT* v, ActT* out, ActT* softmax_lse,
489	    int batch, int n_heads, int seq_len, float scale, cudaStream_t stream)
490	{
491	    using Elem = typename cutlass_elem<ActT>::type;
492	    const int N  = seq_len;
493	    const int D  = kHeadDim;
494	    const int BH = batch * n_heads;
495	    float* lse = reinterpret_cast<float*>(softmax_lse);
496	
497	    // Scratch: FP32 scores [N*N], ActT probs [N*N], FP32 O [N*D].
498	    // Served from per-thread lazily-grown buffers (one static slot each) so the
499	    // forward no longer pays a cudaMalloc/cudaFree per call. Buffers are reused
500	    // across calls and grown on demand; they are NOT freed here (process-lifetime
501	    // reuse, same policy as fmha_get_workspace / sm90_get_workspace).
502	    float* S = reinterpret_cast<float*>(fmha_get_scratch<0>(sizeof(float) * (size_t)N * N));
503	    ActT*  P = reinterpret_cast<ActT*>(fmha_get_scratch<1>(sizeof(ActT) * (size_t)N * N));
504	    float* O = reinterpret_cast<float*>(fmha_get_scratch<2>(sizeof(float) * (size_t)N * D));
505	    if (S == nullptr || P == nullptr || O == nullptr)
506	        return cudaErrorMemoryAllocation;
507	
508	    cudaError_t err = cudaSuccess;
509	    for (int bh = 0; bh < BH && err == cudaSuccess; ++bh) {
510	        const ActT* qh = q + (size_t)bh * N * D;
511	        const ActT* kh = k + (size_t)bh * N * D;
512	        const ActT* vh = v + (size_t)bh * N * D;
513	        ActT*       oh = out + (size_t)bh * N * D;
514	
515	        // S[N,N] = Q[N,D] · Kᵀ[D,N]. K is physically row-major [N,D]. Declaring
516	        // the B operand ColumnMajor over logical {N(=GEMM-N), D(=GEMM-K)} makes
517	        // CUTLASS read that same buffer as Kᵀ, so we get S[i,j]=Σ_d Q[i,d]K[j,d].
518	        err = fmha_sm90_gemm<Elem, cutlass::layout::ColumnMajor>(
519	            N, N, D, qh, kh, S, stream);
520	        if (err != cudaSuccess) break;
521	
522	        // softmax over rows (scaled, optional causal mask) -> P (ActT)
523	        int sm_block = 128;
524	        // 2*N floats: sh[N] working buffer + sraw[N] cp.async S staging buffer.
525	        size_t sm_smem = sizeof(float) * (size_t)N * 2;
526	        fmha_softmax_kernel<ActT, kCausal>
527	            <<<N, sm_block, sm_smem, stream>>>(
528	                S, P, lse ? lse + (size_t)bh * N : nullptr, N, scale);
529	        err = cudaGetLastError();
530	        if (err != cudaSuccess) break;
531	
532	        // O[N,D] = P[N,N] · V[N,D]. V is row-major [N,D] = logical [K=N, N=D],
533	        // so the B operand is RowMajor and read directly.
534	        err = fmha_sm90_gemm<Elem, cutlass::layout::RowMajor>(
535	            N, D, N, P, vh, O, stream);
536	        if (err != cudaSuccess) break;
537	
538	        int total = N * D, cb = 256, cg = (total + cb - 1) / cb;
539	        fmha_cast_kernel<ActT><<<cg, cb, 0, stream>>>(O, oh, total);
540	        err = cudaGetLastError();
541	    }
542	
543	    // S/P/O are reused across calls (process-lifetime per-thread scratch), so
544	    // they are intentionally NOT freed here.
545	    return err;
546	}
547	#endif // WITH_CUTLASS
