549	// ── Forward dispatch ───────────────────────────────────────────────────
550	template <typename ActT, int kHeadDim, bool kCausal>
551	cudaError_t attention_forward(
552	    const ActT* q, const ActT* k, const ActT* v,
553	    ActT* out,
554	    ActT* softmax_lse_act,  // only used to locate the float buffer
555	    int batch, int n_heads, int seq_len,
556	    float scale,
557	    cudaStream_t stream
558	) {
559	    // softmax_lse is always FP32 regardless of ActT
560	    float* softmax_lse = reinterpret_cast<float*>(softmax_lse_act);
561	
562	#ifdef WITH_FLASH_ATTN_3
563	    return flash_attn3_forward<ActT, kHeadDim, kCausal>(
564	        q, k, v, out, reinterpret_cast<ActT*>(softmax_lse),
565	        batch, n_heads, seq_len, scale, stream);
566	#elif defined(WITH_CUTLASS)
567	    // The Sm90 collective FMHA only supports half/bf16 inputs; FP32 activations
568	    // (ActT=float) use the SMEM attention path. Resolved at compile time so
569	    // cutlass_fmha_forward<float> is never instantiated.
570	    if constexpr (cutlass_fmha_supported<ActT>::value) {
571	        return cutlass_fmha_forward<ActT, kHeadDim, kCausal>(
572	            q, k, v, out, reinterpret_cast<ActT*>(softmax_lse),
573	            batch, n_heads, seq_len, scale, stream);
574	    } else {
575	        int grid = batch * n_heads;
576	        int block = 128;
577	        int N = seq_len;
578	        int smem_bytes = (N * N + 2 * N) * sizeof(float);
579	        smem_attention_fwd_kernel<ActT, kHeadDim, kCausal>
580	            <<<grid, block, smem_bytes, stream>>>(
581	                q, k, v, out, softmax_lse, seq_len, scale);
582	        return cudaGetLastError();
583	    }
584	#else
585	    int grid = batch * n_heads;
586	    int block = 128;
587	    int N = seq_len;
588	    int smem_bytes = (N * N + 2 * N) * sizeof(float);
589	    smem_attention_fwd_kernel<ActT, kHeadDim, kCausal>
590	        <<<grid, block, smem_bytes, stream>>>(
591	            q, k, v, out, softmax_lse, seq_len, scale);
592	    return cudaGetLastError();
593	#endif
594	}
595	
596	// ── Backward kernel ────────────────────────────────────────────────────
597	// Recomputes attention weights from softmax_lse (log-sum-exp saved in fwd).
598	// dV = A^T dO, dA = dO V^T, backprop through softmax, dQ = dA' K * scale,
599	// dK = dA'^T Q * scale. All in SMEM for these tiny sequence lengths.
600	
601	template <typename ActT, int kHeadDim, bool kCausal>
602	__global__ void __launch_bounds__(128, 4)
603	smem_attention_bwd_kernel(
604	    const ActT* __restrict__ grad_out,   // [B, H, N, D]
605	    const ActT* __restrict__ q,
606	    const ActT* __restrict__ k,
607	    const ActT* __restrict__ v,
608	    const ActT* __restrict__ attn_out,   // saved forward output
609	    const float* __restrict__ softmax_lse, // [B, H, N]
610	    ActT* __restrict__ grad_q,
611	    ActT* __restrict__ grad_k,
612	    ActT* __restrict__ grad_v,
613	    int seq_len, float scale
614	) {
615	    const int bh = blockIdx.x;
616	    const int tid = threadIdx.x;
617	    const int N = seq_len;
618	    const int D = kHeadDim;
619	    // 64-bit base offset (bh=batch*n_heads can exceed INT_MAX*N*D). See fwd.
620	    const int64_t base = static_cast<int64_t>(bh) * N * D;
621	
622	    extern __shared__ float smem[];
623	    float* scores = smem;               // N * N  (attention weights)
624	    float* dA     = scores + N * N;     // N * N  (grad through attn weights)
625	
626	    // Recompute attention weights from softmax_lse
627	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
628	        int i = idx / N, j = idx % N;
629	        if constexpr (kCausal) {
630	            if (j > i) { scores[idx] = 0.0f; continue; }
631	        }
632	        float dot = 0.0f;
633	        for (int d = 0; d < D; d++)
634	            dot += to_float(q[base + i * D + d])
635	                 * to_float(k[base + j * D + d]);
636	        float lse = softmax_lse[static_cast<int64_t>(bh) * N + i];
637	        scores[idx] = ptx_expf(dot * scale - lse);
638	    }
639	    __syncthreads();
640	
641	    // dV = A^T dO  (accumulated directly to global)
642	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
643	        int j = idx / D, d = idx % D;
644	        float acc = 0.0f;
645	        for (int i = 0; i < N; i++) acc += scores[i * N + j]
646	            * to_float(grad_out[base + i * D + d]);
647	        grad_v[base + idx] = from_float<ActT>(acc);
648	    }
649	    __syncthreads();
650	
651	    // dA = dO V^T
652	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
653	        int i = idx / N, j = idx % N;
654	        float acc = 0.0f;
655	        for (int d = 0; d < D; d++)
656	            acc += to_float(grad_out[base + i * D + d])
657	                 * to_float(v[base + j * D + d]);
658	        dA[idx] = acc;
659	    }
660	    __syncthreads();
661	
662	    // Backprop through softmax: dS_ij = A_ij * (dA_ij - sum_k(A_ik * dA_ik))
663	    for (int i = tid; i < N; i += blockDim.x) {
664	        float dot_sum = 0.0f;
665	        for (int j = 0; j < N; j++) dot_sum += scores[i * N + j] * dA[i * N + j];
666	        for (int j = 0; j < N; j++) {
667	            float ds = scores[i * N + j] * (dA[i * N + j] - dot_sum) * scale;
668	            if constexpr (kCausal) { if (j > i) ds = 0.0f; }
669	            dA[i * N + j] = ds;   // reuse dA storage for dS
670	        }
671	    }
672	    __syncthreads();
673	
674	    // dQ = dS K
675	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
676	        int i = idx / D, d = idx % D;
677	        float acc = 0.0f;
678	        for (int j = 0; j < N; j++)
679	            acc += dA[i * N + j] * to_float(k[base + j * D + d]);
680	        grad_q[base + idx] = from_float<ActT>(acc);
681	    }
682	
683	    // dK = dS^T Q
684	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
685	        int j = idx / D, d = idx % D;
686	        float acc = 0.0f;
687	        for (int i = 0; i < N; i++)
688	            acc += dA[i * N + j] * to_float(q[base + i * D + d]);
689	        grad_k[base + idx] = from_float<ActT>(acc);
690	    }
691	}
692	
693	// ── Backward dispatch ──────────────────────────────────────────────────
694	template <typename ActT, int kHeadDim, bool kCausal>
695	cudaError_t attention_backward(
696	    const ActT* grad_out,
697	    const ActT* q, const ActT* k, const ActT* v,
698	    const ActT* out, const ActT* softmax_lse_act,
699	    ActT* grad_q, ActT* grad_k, ActT* grad_v,
700	    int batch, int n_heads, int seq_len,
701	    float scale,
702	    cudaStream_t stream
703	) {
704	    const float* softmax_lse = reinterpret_cast<const float*>(softmax_lse_act);
705	    int grid = batch * n_heads;
706	    int block = 128;
707	    int N = seq_len;
708	    int smem_bytes = 2 * N * N * sizeof(float);  // scores + dA
709	    smem_attention_bwd_kernel<ActT, kHeadDim, kCausal>
710	        <<<grid, block, smem_bytes, stream>>>(
711	            grad_out, q, k, v, out, softmax_lse,
712	            grad_q, grad_k, grad_v, seq_len, scale);
713	    return cudaGetLastError();
714	}
